"""
Cluster arithmetic: the minimal number of phases equals the maximal cluster size.

Self-contained demonstration (standard library only).  For a family of finite rooted
directed preorders built as stacks of clusters, this script

  * computes the clusters, the antisymmetrisation, and the resulting parameters
    m = number of clusters, c* = largest cluster size;
  * builds the phase-augmented morphism  F : CW_c(1, m) -> P  given by
    "greedy climb on the antisymmetrisation, then read the phase as a choice of
    element inside the cluster reached";
  * verifies forth, back and surjectivity for every phase count c, confirming that
    the representation succeeds exactly when c >= c*, which is the sharpness
    statement: the least usable number of phases is the maximal cluster size.
"""

from __future__ import annotations

from itertools import product
from typing import Callable, Dict, FrozenSet, List, Sequence, Set, Tuple

World = Tuple[int, FrozenSet[int]]
PWorld = Tuple[World, int]


def closure(n: int, edges: Sequence[Tuple[int, int]]) -> Set[Tuple[int, int]]:
    """Reflexive-transitive closure of `edges` on {0, ..., n-1}."""
    rel: Set[Tuple[int, int]] = {(x, x) for x in range(n)} | set(edges)
    changed = True
    while changed:
        changed = False
        for a, b in list(rel):
            for c, d in list(rel):
                if b == c and (a, d) not in rel:
                    rel.add((a, d))
                    changed = True
    return rel


def stack_of_clusters(sizes: Sequence[int]) -> Tuple[int, Set[Tuple[int, int]], List[List[int]]]:
    """The preorder whose clusters of the given sizes are stacked in a chain."""
    groups: List[List[int]] = []
    next_id = 0
    for s in sizes:
        groups.append(list(range(next_id, next_id + s)))
        next_id += s
    edges: List[Tuple[int, int]] = []
    for q, g in enumerate(groups):
        for p in g:
            for p2 in g:
                edges.append((p, p2))
        if q + 1 < len(groups):
            for p in g:
                for p2 in groups[q + 1]:
                    edges.append((p, p2))
    return next_id, closure(next_id, edges), groups


def cube(m: int) -> List[World]:
    """The states of the one-tick clock-and-switch world CW(1, m)."""
    return [(0, frozenset(i for i, b in enumerate(bits) if b))
            for bits in product([False, True], repeat=m)]


def world_leq(w: World, v: World) -> bool:
    """Accessibility in CW(1, m)."""
    return w[0] <= v[0] and w[1] <= v[1]


def greedy_climb_on_chain(m: int) -> Callable[[World], int]:
    """Greedy climb onto the m-element chain of clusters (identity linear extension)."""
    def climb(w: World) -> int:
        pos = 0
        for i in range(m):
            if i in w[1]:
                pos = i if pos <= i else m - 1
        return pos
    return climb


def phase_map(groups: List[List[int]], c: int) -> Callable[[PWorld], int]:
    """F(w, j) = pick(climb(w), j) with pick a choice of element inside a cluster."""
    m = len(groups)
    climb = greedy_climb_on_chain(m)

    def pick(q: int, j: int) -> int:
        members = groups[q]
        return members[j] if j < len(members) else members[0]

    return lambda state: pick(climb(state[0]), state[1])


def verify(n: int, rel: Set[Tuple[int, int]], groups: List[List[int]], c: int
           ) -> Tuple[bool, bool, bool]:
    """Return (forth, back, surjective) for the phase map with `c` phases."""
    m = len(groups)
    F = phase_map(groups, c)
    states: List[PWorld] = [(w, j) for w in cube(m) for j in range(c)]
    le = lambda x, y: (x, y) in rel
    forth = all(le(F(x), F(y)) for x in states for y in states if world_leq(x[0], y[0]))
    back = all(
        any(world_leq(x[0], y[0]) and F(y) == q for y in states)
        for x in states for q in range(n) if le(F(x), q)
    )
    onto = {F(x) for x in states} == set(range(n))
    return forth, back, onto


def main() -> None:
    profiles = [[1, 2, 1], [2, 2], [1, 3, 1], [3, 1, 2], [1, 1, 1, 1]]
    print(f"{'cluster sizes':>18} {'m':>3} {'c*':>3} | verdict for c = 1, 2, 3, 4")
    print("-" * 68)
    for sizes in profiles:
        n, rel, groups = stack_of_clusters(sizes)
        m, c_star = len(groups), max(len(g) for g in groups)
        verdicts = []
        for c in range(1, 5):
            forth, back, onto = verify(n, rel, groups, c)
            ok = forth and back and onto
            verdicts.append("OK " if ok else "-- ")
            # sharpness: success exactly when c >= largest cluster
            assert ok == (c >= c_star)
        print(f"{str(sizes):>18} {m:3d} {c_star:3d} | " + " ".join(verdicts))
    print()
    print("In every case the representation succeeds precisely for c >= c*,")
    print("so the least usable number of phases is exactly the maximal cluster size.")


if __name__ == "__main__":
    main()

