"""
Visualization: the switch cube folding onto a poset under the greedy climb.

Draws the Hasse diagram of the clock-and-switch world CW(1, 4) -- the 4-dimensional
switch cube, laid out in columns by the number of switches that are on -- with every
vertex coloured by the point of the diamond poset 0 < a, b < 1 that the greedy climb
sends it to.  The diamond itself is drawn beside it in the same colours, so the reader
can see the 16 states of the machine folding onto the 4 states of the shadow while
every edge of the cube maps to a genuine transition of the shadow.

Requires: matplotlib.  Produces `greedy_climb_fold.png`.
"""

from __future__ import annotations

from typing import Dict, List, Tuple

import matplotlib.pyplot as plt


def diamond_leq() -> Dict[Tuple[int, int], bool]:
    """Order relation of the diamond 0 < a, b < 1 with points 0, 1(=a), 2(=b), 3."""
    pairs = [(0, 0), (1, 1), (2, 2), (3, 3), (0, 1), (0, 2), (0, 3), (1, 3), (2, 3)]
    return {(x, y): ((x, y) in pairs) for x in range(4) for y in range(4)}


def greedy_climb_image(mask: int, order: List[int], le: Dict[Tuple[int, int], bool],
                       root: int, top: int) -> int:
    """Image of the switch configuration `mask` under the greedy climb."""
    pos = root
    for i, target in enumerate(order):
        if mask & (1 << i):
            pos = target if le[(pos, target)] else top
    return pos


def main() -> None:
    le = diamond_leq()
    order = [0, 1, 2, 3]          # a linear extension of the diamond
    root, top, m = 0, 3, 4
    names = {0: "0", 1: "a", 2: "b", 3: "1"}
    colours = {0: "#7dd3fc", 1: "#f9a8d4", 2: "#fcd34d", 3: "#86efac"}

    image = {w: greedy_climb_image(w, order, le, root, top) for w in range(1 << m)}

    columns: Dict[int, List[int]] = {}
    for w in range(1 << m):
        columns.setdefault(bin(w).count("1"), []).append(w)
    coord: Dict[int, Tuple[float, float]] = {}
    for k, ws in columns.items():
        for idx, w in enumerate(ws):
            coord[w] = (float(k), idx - (len(ws) - 1) / 2.0)

    fig, (ax_cube, ax_poset) = plt.subplots(
        1, 2, figsize=(13, 6), gridspec_kw={"width_ratios": [3, 1]}
    )

    for w in range(1 << m):
        for i in range(m):
            if not (w & (1 << i)):
                v = w | (1 << i)
                x1, y1 = coord[w]
                x2, y2 = coord[v]
                ax_cube.plot([x1, x2], [y1, y2], color="#c9cee6", lw=0.8, zorder=1)
    for w in range(1 << m):
        x, y = coord[w]
        ax_cube.scatter([x], [y], s=260, c=colours[image[w]], edgecolors="#20233a",
                        zorder=2, linewidths=1.2)
        ax_cube.text(x, y, names[image[w]], ha="center", va="center", fontsize=9,
                     fontweight="bold", zorder=3)
    ax_cube.set_title("CW(1, 4): 16 machine states, coloured by their image", fontsize=12)
    ax_cube.set_xlabel("number of switches that are on")
    ax_cube.set_yticks([])
    ax_cube.spines[["top", "right", "left"]].set_visible(False)

    positions = {0: (0.0, 0.0), 1: (-0.7, 1.0), 2: (0.7, 1.0), 3: (0.0, 2.0)}
    for a, b in [(0, 1), (0, 2), (1, 3), (2, 3)]:
        ax_poset.plot([positions[a][0], positions[b][0]],
                      [positions[a][1], positions[b][1]], color="#c9cee6", lw=1.4, zorder=1)
    for p, (x, y) in positions.items():
        ax_poset.scatter([x], [y], s=520, c=colours[p], edgecolors="#20233a",
                         zorder=2, linewidths=1.4)
        ax_poset.text(x, y, names[p], ha="center", va="center", fontsize=12, fontweight="bold",
                      zorder=3)
    ax_poset.set_title("the shadow: the diamond", fontsize=12)
    ax_poset.set_xlim(-1.4, 1.4)
    ax_poset.set_ylim(-0.5, 2.5)
    ax_poset.axis("off")

    fig.suptitle("The greedy climb folds the switch cube onto a finite ordered set",
                 fontsize=14)
    fig.tight_layout()
    fig.savefig("greedy_climb_fold.png", dpi=160)
    print("wrote greedy_climb_fold.png")


if __name__ == "__main__":
    main()
